package com.bank.topn.repository;
import com.bank.topn.model.Account;
import java.math.BigDecimal;
import java.util.*;
import java.util.stream.*;

public class AccountRepository {
    private final List<Account> all = List.of(
        new Account("SAV2001","Rajesh Kumar","DELHI", new BigDecimal("1000000.00")),
        new Account("CUR3001","Priya Sharma","DELHI", new BigDecimal("250000.00")),
        new Account("SAV2002","Amit Verma","DELHI",   new BigDecimal("400000.00")),
        new Account("SAV2003","Neha Gupta","DELHI",   new BigDecimal("900000.00")),
        new Account("SAV9001","Vikram Rao","MUMBAI",  new BigDecimal("700000.00")));
    public List<String> branches() {
        return all.stream().map(Account::getBranch).distinct().collect(Collectors.toList());
    }
    // Mimics LATERAL inner query: top N by balance for ONE branch
    public List<Account> topNForBranch(String branch, int n) {
        return all.stream().filter(a -> a.getBranch().equals(branch))
            .sorted(Comparator.comparing(Account::getBalance).reversed())
            .limit(n).collect(Collectors.toList());
    }
}
