package com.bank.topn.service;
import com.bank.topn.model.Account;
import com.bank.topn.repository.AccountRepository;
import java.util.*;
import java.util.logging.*;

public class RankingService {
    private static final Logger log = Logger.getLogger(RankingService.class.getName());
    static {
        Handler h = new ConsoleHandler(); h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false); log.addHandler(h);
    }
    private final AccountRepository repo;
    public RankingService(AccountRepository repo) { this.repo = repo; }

    public Map<String, List<Account>> topNPerBranch(int n) {
        Map<String, List<Account>> out = new LinkedHashMap<>();
        for (String branch : repo.branches()) {           // loop groups
            List<Account> top = repo.topNForBranch(branch, n);  // LATERAL inner
            out.put(branch, top);
            log.info(() -> "branch " + branch + " top" + n + " = " + top.stream().map(Account::getId).toList());
        }
        return out;
    }
}
