package com.bank.topn;
import com.bank.topn.repository.AccountRepository;
import com.bank.topn.service.RankingService;
import java.util.logging.*;

public class TopNDemo {
    public static void main(String[] args) {
        RankingService svc = new RankingService(new AccountRepository());
        svc.topNPerBranch(3).forEach((branch, list) ->
            list.forEach(a -> System.out.println(branch + " | " + a.getId() + " | " + a.getBalance())));
    }
}

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n", r.getMillis(), r.getLevel(), formatMessage(r));
    }
}
